from __future__ import annotations

from dataclasses import dataclass
from functools import partial
from types import MappingProxyType
from typing import Callable


@dataclass(frozen=True)
class Method:
    required: str
    optional: str
    description: str
    handler: Callable
    effect: str = "read"
    cancellable: bool = False
    pausable: bool = False
    job_kind: str = ""
    family: str = ""
    item_method: str = ""

    def __post_init__(self):
        if self.effect not in {"read", "write", "control"}:
            raise ValueError("Unknown method effect.")
        if self.pausable and not self.cancellable:
            raise ValueError("Pausable methods must support cancellation.")

    @property
    def mutating(self):
        return self.effect != "read"


def _batch(name, service, params):
    from .batch import start
    return start(service, name, params)


def _custom_game(name, service, params):
    return service._custom_game(name, params)


def _workflow(name, service, params):
    return service._client_workflows.call(name, params)


