METHOD_NAMES = tuple(REGISTRY)
MUTATIONS = tuple(name.removesuffix(".start") for name, method in REGISTRY.items() if method.effect == "write")
CANCELLABLE_JOBS = tuple(dict.fromkeys(method.job_kind or name.removesuffix(".start")
                                     for name, method in REGISTRY.items() if method.cancellable))
PAUSABLE_JOBS = tuple(dict.fromkeys(method.job_kind or name.removesuffix(".start")
                                  for name, method in REGISTRY.items() if method.pausable))


def contracts(family=None):
    return {name: (method.required, method.optional, method.description)
            for name, method in REGISTRY.items() if family is None or method.family == family}
